                if nv > dp[cal]:
                    dp[cal] = nv

        for cal in range(1, X + 1):
            if dp[cal - 1] > dp[cal]:
                dp[cal] = dp[cal - 1]

        best.append(dp)

    def feasible(target):
        total_cal = 0
        for dp in best:
